/* SmsCousMapper.insertEcmUser : 사용자관리 Insert */
INSERT INTO TB_SMS_USER(
   ENT_CODE
  ,USER_ID
  ,USER_LOGIN_ID
  ,USER_LOGIN_PW
  ,USER_TYPE
  ,USER_NAME
  ,USER_NAME_ENG
  ,POSITION_CODE
  ,DEPARTMENT_CODE
  ,USER_TEL
  ,USER_CELLPHONE
  ,USER_EMAIL
  ,USE_YN
  ,ENT_BUSINESS_CODE
  ,CUSTOMER_CODE	  
  ,USER_ADDRESS
  ,USER_ADDRESS_A
  ,USER_ADDRESS_B
  ,REGISTER_USER_ID
  ,REGISTER_DATE_TIME
  ,UPDATE_USER_ID
  ,UPDATE_DATE_TIME
)VALUES(
	   #{entCode}
	  ,#{userId}
	  ,#{userLoginId}
	  ,#{userLoginPw}
	  ,#{userType}
	  ,#{userName}
	  ,#{userName}
	  ,#{positionCode}
	  ,#{departmentCode}
	  ,#{userTel}
	  ,#{userCellphone}
	  ,#{userEmail}
	  ,#{useYn}
	  ,#{entBusinessCode}
	  ,#{customerCode}
	  ,#{userAddress}
  	  ,#{userAddressA}
  	  ,#{userAddressB}
	  ,#{updateUserId}
	  ,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
	  ,#{updateUserId}
	  ,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
)

/* SmsCousMapper.insertEcmUserOption : 사용자관리 Insert */
