INSERT INTO TB_SMS_USER_OPTION(
	   ENT_CODE
	  ,USER_ID				 
	  ,USER_CLASS
	  ,SEARCH_OPTION_HIDE_YN
	  ,SEARCH_START_TERM
	  ,SEARCH_END_TERM
	  ,SEARCH_ALL_USER_YN
	  ,SEARCH_DEFAULT_USER_YN
	  ,PW_UPDATE_DAYS
	  ,PW_UPDATE_DATE
	  ,PW_ERROR_COUNT
	  ,PW_UPDATE_ALERT_DAYS
	  ,SPREAD_YN
	  ,VALID_USE_DAYS
	  ,DEFAULT_SOLUTION_CODE
	  ,DEFAULT_BOUND
	  ,DEFAULT_BOUND_TYPE
	  ,REGISTER_USER_ID
	  ,REGISTER_DATE_TIME
	  ,UPDATE_USER_ID
	  ,UPDATE_DATE_TIME
)VALUES(
	   #{entCode}
	  ,#{userId}
	  ,#{userClass}
	  ,#{searchOptionHideYn}
	  ,#{searchStartTerm}
	  ,#{searchEndTerm}
	  ,#{searchAllUserYn}
	  ,#{searchDefaultUserYn}
	  ,#{pwUpdateDays}
	  ,CONVERT(VARCHAR,#{pwUpdateDate}, CAST(#{dateFormat} AS INT))
	  ,#{pwErrorCount}
	  ,#{pwUpdateAlertDays}
