/* SmsCousMapper.updateEcmUser : 사용자관리 Update */
UPDATE TB_SMS_USER SET
	   USER_LOGIN_ID = #{userLoginId}
	  ,USER_NAME = #{userName}
	  ,USER_TEL = #{userTel}
	  ,USER_CELLPHONE = #{userCellphone}
	  ,USER_EMAIL = #{userEmail}
	  ,USE_YN = #{useYn}
	  ,ENT_BUSINESS_CODE = #{entBusinessCode}
	  ,CUSTOMER_CODE = #{customerCode}      
  	  ,USER_ADDRESS = #{userAddress}   
  	  ,USER_ADDRESS_A = #{userAddressA}
  	  ,USER_ADDRESS_B = #{userAddressB}		  	    
	  ,UPDATE_USER_ID = #{updateUserId}
	  ,UPDATE_DATE_TIME = CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
WHERE ENT_CODE = #{entCode}
AND USER_ID = #{userId};
UPDATE TB_SMS_USER_OPTION SET				
	  SEARCH_OPTION_HIDE_YN = #{searchOptionHideYn}
	  ,SEARCH_START_TERM = #{searchStartTerm}
	  ,SEARCH_END_TERM = #{searchEndTerm}
	  ,SEARCH_ALL_USER_YN = #{searchAllUserYn}
	  ,SEARCH_DEFAULT_USER_YN = #{searchDefaultUserYn}
	  ,PW_UPDATE_DAYS = #{pwUpdateDays}
	  ,PW_UPDATE_DATE = CONVERT(VARCHAR,#{pwUpdateDate}, CAST(#{dateFormat} AS INT))
	  ,PW_ERROR_COUNT = #{pwErrorCount}
	  ,PW_UPDATE_ALERT_DAYS = #{pwUpdateAlertDays}
	  ,SPREAD_YN = #{spreadYn}
	  ,VALID_USE_DAYS = #{validUseDays}
	  ,DEFAULT_SOLUTION_CODE = #{defaultSolutionCode}
	  ,DEFAULT_BOUND = #{defaultBound}
	  ,DEFAULT_BOUND_TYPE = #{defaultBoundType}
	  ,UPDATE_USER_ID = #{updateUserId}
	  ,UPDATE_DATE_TIME = CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
WHERE ENT_CODE = #{entCode}
AND USER_ID = #{userId};

mapper.select:
/* SmsCousMapper.selectMakeUserId : 사용자관리 아이디 생성 */
SELECT CONCAT(LEFT(CONVERT(varchar, GETDATE(),112),6)
	   , '-'
	   ,CONCAT(REPLICATE('0', 3-LEN(ISNULL(( SELECT MAX(CEILING(SUBSTRING(USER_ID, 8, 3))) + 1 FROM TB_SMS_USER
					 						 WHERE USER_ID LIKE CONCAT(LEFT(CONVERT(varchar, GETDATE(),112),6), '-%')), 1)))
			   ,ISNULL((SELECT MAX(CEILING(SUBSTRING(USER_ID, 8, 3))) + 1 FROM TB_SMS_USER
				     	WHERE USER_ID LIKE CONCAT(LEFT(CONVERT(varchar, GETDATE(),112),6), '-%')), 1)
			   )



) AS USER_ID

/* SmsCousMapper.selectEcmCustomerList : Customer List */ SELECT cus.ENT_CODE ,dbo.GET_CUS_TREE(cus.ENT_CODE,cus.CUSTOMER_CODE,'SUB_CNT') AS COUNT ,cus.CUSTOMER_CODE ,cus.CUSTOMER_NAME ,cus.REGISTER_DATE_TIME ,cus.CUSTOMER_TYPE FROM TB_SMS_CUSTOMER cus WHERE cus.ENT_CODE = #{srchEntCode} /*AND 1 = (SELECT COUNT(1) FROM TB_SMS_CUSTOMER_SOLUTION sol WHERE sol.ENT_CODE = cus.ENT_CODE AND sol.CUSTOMER_CODE = cus.CUSTOMER_CODE AND sol.SOLUTION = 'ECM')*/
AND cus.CUSTOMER_TYPE IN ('HC','BR')
AND cus.CUSTOMER_TYPE IN ('SC')
AND ISNULL(cus.PARENT_CUSTOMER_CODE,'') = ''
AND cus.CUSTOMER_TYPE = #{srchCustomerType}
AND cus.CUSTOMER_CODE = #{srchCustomerCode}
AND cus.CUSTOMER_NAME LIKE CONCAT('%',#{srchCustomerName},'%')

/* SmsCousMapper.selectEcmCustomerAllList : Customer List */
SELECT cus.ENT_CODE ,dbo.GET_CUS_TREE(cus.ENT_CODE,cus.CUSTOMER_CODE,'SUB_CNT') AS COUNT ,cus.CUSTOMER_CODE ,cus.CUSTOMER_NAME ,CONVERT(VARCHAR(16), cus.REGISTER_DATE_TIME, 20) AS REGISTER_DATE_TIME ,cus.CUSTOMER_TYPE ,cus.AMS_COUNTRY_CODE ,cus.PARENT_CUSTOMER_CODE ,cus.DELIVERY_CODE ,cus.CB_CODE ,cus.LB_CFT_TYPE ,cus.CURRENCY_CODE ,cus.EXCEL_TYPE ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = cus.ENT_CODE AND CUSTOMER_CODE = cus.PARENT_CUSTOMER_CODE) AS PARENT_CUSTOMER_NAME ,dbo.GET_CUS_TREE(cus.ENT_CODE,cus.CUSTOMER_CODE,'SUB_LIST') AS LOW_LIST ,cus.USE_YN ,inf.BUSINESS_ID ,CASE WHEN fs.FILE_COUNT > 0 THEN 'Y' ELSE 'N' END AS FILE_SHARE ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = cus.ENT_CODE AND CUSTOMER_CODE = cus.CB_CODE) AS CB_NAME ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = cus.ENT_CODE AND GROUP_CODE = 'ECM_DELIVERY_CODE' AND CODE = cus.DELIVERY_CODE) AS DELIVERY_NAME ,(SELECT COUNT(*) FROM TB_SMS_USER WHERE ENT_CODE = cus.ENT_CODE AND CUSTOMER_CODE = cus.CUSTOMER_CODE) AS USER_COUNT FROM TB_SMS_CUSTOMER cus LEFT JOIN VTB_SMS_BUSINESS_REG_INFO inf ON inf.ENT_CODE = cus.ENT_CODE AND inf.REGISTRATION_CODE = cus.REGISTRATION_CODE LEFT JOIN ( SELECT ISNULL(COUNT(FUNC_JOB_NO), 0) AS FILE_COUNT ,MAX(fs.ENT_CODE) AS ENT_CODE ,MAX(fs.FUNC_JOB_NO) AS FUNC_JOB_NO FROM TB_COM_FILE_SHARE fs WHERE ENT_CODE = #{srchEntCode} AND FUNC_TYPE = 'CUSTOMER' GROUP BY FUNC_JOB_NO ) fs ON fs.ENT_CODE = cus.ENT_CODE AND fs.FUNC_JOB_NO = cus.CUSTOMER_CODE WHERE cus.ENT_CODE = #{srchEntCode} /*AND 1 = (SELECT COUNT(1) FROM TB_SMS_CUSTOMER_SOLUTION sol WHERE sol.ENT_CODE = cus.ENT_CODE AND sol.CUSTOMER_CODE = cus.CUSTOMER_CODE AND sol.SOLUTION = 'ECM')*/
AND cus.CUSTOMER_TYPE = #{srchCustomerType}
AND cus.CUSTOMER_TYPE IN('HC', 'BR','SC')
AND cus.CUSTOMER_CODE = #{srchCustomerCode}
AND cus.CUSTOMER_NAME LIKE CONCAT('%',#{srchCustomerName},'%')

/* SmsCousMapper.selectEcmCustomerDetail : Ecm Customer Detail */ SELECT ENT_CODE ,CUSTOMER_CODE
,SEND_MODIFY_YN
,CUSTOMER_TYPE ,USE_YN ,CUSTOMER_NAME ,CUSTOMER_NAME_ENG ,ADDRESS_ENG ,ADDRESS_A_ENG ,ADDRESS_B_ENG ,ATTN_ENG ,TEL_ENG ,FAX_ENG ,ADDRESS ,ADDRESS_A ,ADDRESS_B ,ATTN ,ATTN_HP ,TEL ,FAX ,EMAIL ,HOME_PAGE_URL ,ACCOUNT_CODE ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = cus.ENT_CODE AND CUSTOMER_CODE = cus.ACCOUNT_CODE) AS ACCOUNT_NAME ,CB_CODE ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = cus.ENT_CODE AND CUSTOMER_CODE = cus.CB_CODE) AS CB_NAME ,DELIVERY_CODE ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = cus.ENT_CODE AND GROUP_CODE = 'ECM_DELIVERY_CODE' AND CODE = cus.DELIVERY_CODE) AS DELIVERY_NAME ,EXCEL_TYPE ,LB_CFT_TYPE ,CURRENCY_CODE ,CONSOL_USE_YN ,AMS_COUNTRY_CODE ,REGISTER_DATE_TIME ,UPDATE_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = cus.ENT_CODE AND USER_ID = cus.register_user_id) AS REGISTER_USER_NAME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = cus.ENT_CODE AND USER_ID = cus.update_user_id) AS UPDATE_USER_NAME ,ECM_INVOICE_YN ,ORIG_CODE ,GOODS_LOC_CODE ,GOODS_LOC_ADDR ,BWH_NAME ,CUSTOMS_DPT_CODE ,CUSTOMS_ID ,CUSTOMS_CODE ,INCOTERMS ,AMS_ZIPCODE ,AMS_STATE ,CONCAT(AMS_STREET,AMS_STREET_2) AS AMS_STREET ,AMS_PLACE ,CUSTOMER_CUSTOMS_ID_TYPE ,CUSTOMER_BUSINESS_ID ,CUSTOMER_BUSINESS_NAME ,CUSTOMER_BUSINESS_PRESIDENT ,CUSTOMER_BUSINESS_ADDRESS ,CUSTOMER_EXP_TRANS_TYPE ,CUSTOMER_GST_NO ,DECLARATION_REG_NO FROM TB_SMS_CUSTOMER cus WHERE cus.ENT_CODE = #{entCode} AND cus.CUSTOMER_CODE = #{customerCode}

