/* SmsCousMapper.insertEcmCustomer : ECM 거래처정보 Insert */
INSERT INTO TB_SMS_CUSTOMER(
	ENT_CODE
	
		,SEND_MODIFY_YN
	
	,CUSTOMER_CODE
	,CUSTOMER_TYPE		  
	,CUSTOMER_NAME
	,CUSTOMER_NAME_ENG
	,ADDRESS_ENG
	,ADDRESS_A_ENG
	,ADDRESS_B_ENG
	,ATTN_ENG
	,TEL_ENG
	,FAX_ENG
	,ADDRESS
	,ADDRESS_A
	,ADDRESS_B
	,ATTN
	,ATTN_HP
	,TEL
	,FAX
	,EMAIL
	,HOME_PAGE_URL
	,ACCOUNT_CODE
	,CB_CODE
	,DELIVERY_CODE
	,EXCEL_TYPE
	,LB_CFT_TYPE
	,AMS_COUNTRY_CODE
	,CURRENCY_CODE
	,USE_YN
	,CUSTOMER_LEVEL
	,CONSOL_USE_YN
	,REGISTER_USER_ID
	,REGISTER_DATE_TIME
	,UPDATE_USER_ID
	,UPDATE_DATE_TIME
	,ECM_INVOICE_YN
	,ORIG_CODE
	,GOODS_LOC_CODE		
	,GOODS_LOC_ADDR		
	,BWH_NAME			
	,CUSTOMS_DPT_CODE	
	,CUSTOMS_ID			
	,CUSTOMS_CODE
	,INCOTERMS
	,AMS_ZIPCODE
	,AMS_STATE
	,AMS_PLACE
	,AMS_STREET
	,AMS_STREET_2
	,CUSTOMER_CUSTOMS_ID_TYPE
	,CUSTOMER_BUSINESS_ID
	,CUSTOMER_BUSINESS_NAME
	,CUSTOMER_BUSINESS_PRESIDENT
	,CUSTOMER_BUSINESS_ADDRESS
	,CUSTOMER_EXP_TRANS_TYPE
	,CUSTOMER_GST_NO
	,DECLARATION_REG_NO
)VALUES(
    #{entCode}
	
		,#{sendModifyYn}
	
	,#{customerCode}
	,#{customerType}
	,#{customerName}
	,#{customerNameEng}
	,#{addressEng}
	,#{addressAEng}
	,#{addressBEng}
	,#{attnEng}
	,#{telEng}
	,#{faxEng}
	,#{address}
	,#{addressA}
	,#{addressB}
	,#{attn}
	,#{attnHp}
	,#{tel}
	,#{fax}
	,#{email}
	,#{homePageUrl}	
	,#{accountCode}	
	,#{cbCode}	
	,#{deliveryCode}	
	,#{excelType}	
	,#{lbCftType}
	,#{amsCountryCode}	
	,#{currencyCode}	
	,#{useYn}	
	,CASE WHEN #{customerType} IN ('HC','BR') THEN '1' END
	,#{consolUseYn}	
	,#{updateUserId}
	,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
	,#{updateUserId}
	,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
	,#{ecmInvoiceYn}
	,#{origCode}       
	,#{goodsLocCode}   
	,#{goodsLocAddr}   
	,#{bwhName}        
	,#{customsDptCode} 
	,#{customsId}      
	,#{customsCode}
	,#{incoterms}
	,#{amsZipcode}
	,#{amsState}
	,#{amsPlace}
	,SUBSTRING(ISNULL(CAST(#{amsStreet} AS NVARCHAR(70)), ''), 1, 35)
	,SUBSTRING(ISNULL(CAST(#{amsStreet} AS NVARCHAR(70)), ''), 36, 70)
	,#{customerCustomsIdType}
	,#{customerBusinessId}
	,#{customerBusinessName}
	,#{customerBusinessPresident}
	,#{customerBusinessAddress}
	,#{customerExpTransType}
	,#{customerGstNo}
	,#{declarationRegNo}
)

		/* SmsCousMapper.insertEcmCustomerSolution : ECM 거래처정보 솔루션 Insert */
		INSERT INTO dbo.TB_SMS_CUSTOMER_SOLUTION
            (ENT_CODE
            ,CUSTOMER_CODE
            ,SOLUTION
            ,REGISTER_USER_ID
            ,REGISTER_DATE_TIME
            ,UPDATE_USER_ID
            ,UPDATE_DATE_TIME)
     	VALUES
           (
             #{entCode}
			,#{customerCode}
			,#{solution}
			,#{updateUserId}
			,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
			,#{updateUserId}
			,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
			)

		/* SmsCousMapper.insertEcmCustomer : ECM 거래처정보 사업장 Insert */
		INSERT INTO dbo.TB_SMS_CUSTOMER_BUSINESS
            (ENT_CODE
            ,CUSTOMER_CODE
            ,ENT_BUSINESS_CODE
            ,REGISTER_USER_ID
            ,REGISTER_DATE_TIME
            ,UPDATE_USER_ID
            ,UPDATE_DATE_TIME)
     	VALUES
           (
             #{entCode}
			,#{customerCode}
			,(SELECT TOP 1 ENT_BUSINESS_CODE FROM TB_SMS_ENT_BUSINESS WHERE HEAD_BUSINESS_YN = 'Y')
			,#{updateUserId}
			,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
			,#{updateUserId}
			,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
			)

/* SmsCousMapper.insertEcmCustomerBankInfo : ECM 거래처정보 Bank Info Insert */
INSERT INTO dbo.TB_SMS_CUSTOMER_BANK(
		   ENT_CODE
		  ,CUSTOMER_CODE
		  ,SOLUTION
		  ,BOUND
		  ,BOUND_TYPE
		  ,BANK_ACCOUNTS_CODE
		  ,BANK_CODE
		  ,BANK_ACCOUNT_NO
		  ,BANK_DEPOSITOR
		  ,BANK_OFFICE_NAME
		  ,BANK_ASSIGN_DATE
		  ,PRINT_YN
		  ,REMARKS
		  ,DISPLAY_INDEX
		  ,CURRENCY_CODE
		  ,USE_YN
		  ,PAYMENT_ACCOUNTS_YN
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
	)VALUES(
		   #{entCode}
		  ,#{customerCode}
		  ,#{solution}
		  ,#{bankInfo.bound}
		  ,#{bankInfo.boundType}
		  ,CONCAT(#{bankInfo.bankCode},'-',#{customerCode},'01')
		  ,#{bankInfo.bankCode}
		  ,#{bankInfo.bankAccountNo}
		  ,#{bankInfo.bankDepositor}
		  ,#{bankInfo.bankOfficeName}
		  ,CONVERT(VARCHAR,CASE WHEN #{bankInfo.bankAssignDate} IS NULL THEN GETDATE() ELSE #{bankInfo.bankAssignDate} END, CAST(#{dateFormat} AS INT))
		  ,#{bankInfo.printYn}
		  ,#{bankInfo.remarks}
		  ,#{bankInfo.displayIndex}
		  ,#{bankInfo.currencyCode}
		  ,#{bankInfo.useYn}
		  ,#{bankInfo.paymentAccountsYn}
		  ,#{updateUserId}
		  
		  
		  ,#{bankInfo.registerDateTime}
		  
		  
		  ,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
		  
		  
		  ,#{updateUserId}
		  ,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
	)

