/* SmsCousMapper.updateEcmCustomer : ECM 거래처정보 Update */
UPDATE TB_SMS_CUSTOMER
SET		  
	CUSTOMER_NAME  				= #{customerName}
	,CUSTOMER_NAME_ENG			= #{customerNameEng}
	,ADDRESS_ENG      			= #{addressEng}
	
	,SEND_MODIFY_YN				= #{sendModifyYn}
	
	,ADDRESS_A_ENG    			= #{addressAEng}
	,ADDRESS_B_ENG    			= #{addressBEng}
	,ATTN_ENG         			= #{attnEng}
	,TEL_ENG          			= #{telEng}
	,FAX_ENG          			= #{faxEng}
	,ADDRESS          			= #{address}
	,ADDRESS_A        			= #{addressA}
	,ADDRESS_B        			= #{addressB}
	,ATTN             			= #{attn}
	,ATTN_HP          			= #{attnHp}
	,TEL              			= #{tel}
	,FAX              			= #{fax}
	,EMAIL            			= #{email}
	,HOME_PAGE_URL    			= #{homePageUrl}	
	,ACCOUNT_CODE               = #{accountCode}			                                      
	,CB_CODE              		= #{cbCode}	    
	,DELIVERY_CODE        		= #{deliveryCode}	    
	,EXCEL_TYPE     			= #{excelType}	
	,LB_CFT_TYPE    			= #{lbCftType}	
	,AMS_COUNTRY_CODE			= #{amsCountryCode}	
	,CURRENCY_CODE				= #{currencyCode}	
	,USE_YN         			= #{useYn}	  
	,CONSOL_USE_YN         			= #{consolUseYn}
	
	,UPDATE_USER_ID   			= #{updateUserId}
	,UPDATE_DATE_TIME 			= CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
	,ECM_INVOICE_YN				= #{ecmInvoiceYn}
	,ORIG_CODE					= #{origCode}
	,GOODS_LOC_CODE				= #{goodsLocCode}
	,GOODS_LOC_ADDR				= #{goodsLocAddr}
	,BWH_NAME					= #{bwhName}
	,CUSTOMS_DPT_CODE			= #{customsDptCode}
	,CUSTOMS_ID					= #{customsId}
	,CUSTOMS_CODE				= #{customsCode}
	,INCOTERMS					= #{incoterms}
	,AMS_ZIPCODE				= #{amsZipcode}
	,AMS_STATE					= #{amsState}
	,AMS_PLACE					= #{amsPlace}
	,AMS_STREET					= SUBSTRING(ISNULL(CAST(#{amsStreet} AS NVARCHAR(70)), ''), 1, 35)
	,AMS_STREET_2				= SUBSTRING(ISNULL(CAST(#{amsStreet} AS NVARCHAR(70)), ''), 36, 70)
	,CUSTOMER_CUSTOMS_ID_TYPE	= #{customerCustomsIdType}
	,CUSTOMER_BUSINESS_ID		= #{customerBusinessId}
	,CUSTOMER_BUSINESS_NAME		= #{customerBusinessName}
	,CUSTOMER_BUSINESS_PRESIDENT = #{customerBusinessPresident}
	,CUSTOMER_BUSINESS_ADDRESS	= #{customerBusinessAddress}
	,CUSTOMER_EXP_TRANS_TYPE	= #{customerExpTransType}
	,CUSTOMER_GST_NO			= #{customerGstNo}
	,DECLARATION_REG_NO			= #{declarationRegNo}
WHERE 
	ENT_CODE = #{entCode}
	AND CUSTOMER_CODE = #{customerCode}

/* SmsCousMapper.mappingExec : ECM 거래처정보 맵핑 또는 해제 */


	UPDATE TB_SMS_CUSTOMER
	SET		  
		PARENT_CUSTOMER_CODE		= #{parentCustomerCode}
		,UPDATE_USER_ID   			= #{updateUserId}
		,UPDATE_DATE_TIME 			= CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
	WHERE 
		ENT_CODE = #{entCode}
		AND CUSTOMER_CODE IN 
		
			#{item.customerCode}
		



	UPDATE TB_SMS_CUSTOMER
	SET		  
		PARENT_CUSTOMER_CODE		= ''
		,UPDATE_USER_ID   			= #{updateUserId}
		,UPDATE_DATE_TIME 			= CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
	WHERE 
		ENT_CODE = #{entCode}
		AND CUSTOMER_CODE IN 
		
			#{item.customerCode}

/* SmsCousMapper.mappingExec : ECM 거래처정보 맵핑 또는 해제 */


	UPDATE TB_SMS_CUSTOMER
	SET		  
		CUSTOMER_LEVEL = dbo.GET_CUS_TREE(ENT_CODE,CUSTOMER_CODE,'LEV') 
		,UPDATE_USER_ID   			= #{updateUserId}
		,UPDATE_DATE_TIME 			= CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
	WHERE 
		ENT_CODE = #{entCode}
		AND CUSTOMER_CODE IN 
		
			#{item.customerCode}
		



	UPDATE TB_SMS_CUSTOMER
	SET		  
		CUSTOMER_LEVEL = ''
		,UPDATE_USER_ID   			= #{updateUserId}
		,UPDATE_DATE_TIME 			= CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
	WHERE 
		ENT_CODE = #{entCode}
		AND CUSTOMER_CODE IN 
		
			#{item.customerCode}

