/* SmsCousMapper.selectEcmCustomerAllList : Customer List */
SELECT cus.ENT_CODE ,dbo.GET_CUS_TREE(cus.ENT_CODE,cus.CUSTOMER_CODE,'SUB_CNT') AS COUNT ,cus.CUSTOMER_CODE ,cus.CUSTOMER_NAME ,CONVERT(VARCHAR(16), cus.REGISTER_DATE_TIME, 20) AS REGISTER_DATE_TIME ,cus.CUSTOMER_TYPE ,cus.AMS_COUNTRY_CODE ,cus.PARENT_CUSTOMER_CODE ,cus.DELIVERY_CODE ,cus.CB_CODE ,cus.LB_CFT_TYPE ,cus.CURRENCY_CODE ,cus.EXCEL_TYPE ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = cus.ENT_CODE AND CUSTOMER_CODE = cus.PARENT_CUSTOMER_CODE) AS PARENT_CUSTOMER_NAME ,dbo.GET_CUS_TREE(cus.ENT_CODE,cus.CUSTOMER_CODE,'SUB_LIST') AS LOW_LIST ,cus.USE_YN ,inf.BUSINESS_ID ,CASE WHEN fs.FILE_COUNT > 0 THEN 'Y' ELSE 'N' END AS FILE_SHARE ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = cus.ENT_CODE AND CUSTOMER_CODE = cus.CB_CODE) AS CB_NAME ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = cus.ENT_CODE AND GROUP_CODE = 'ECM_DELIVERY_CODE' AND CODE = cus.DELIVERY_CODE) AS DELIVERY_NAME ,(SELECT COUNT(*) FROM TB_SMS_USER WHERE ENT_CODE = cus.ENT_CODE AND CUSTOMER_CODE = cus.CUSTOMER_CODE) AS USER_COUNT ,(SELECT COUNT(*) FROM TB_SMS_USER WHERE ENT_CODE = cus.ENT_CODE AND CUSTOMER_CODE = cus.CUSTOMER_CODE AND USE_YN = 'N') AS USER_COUNT_BEFORE FROM TB_SMS_CUSTOMER cus LEFT JOIN VTB_SMS_BUSINESS_REG_INFO inf ON inf.ENT_CODE = cus.ENT_CODE AND inf.REGISTRATION_CODE = cus.REGISTRATION_CODE LEFT JOIN ( SELECT ISNULL(COUNT(FUNC_JOB_NO), 0) AS FILE_COUNT ,MAX(fs.ENT_CODE) AS ENT_CODE ,MAX(fs.FUNC_JOB_NO) AS FUNC_JOB_NO FROM TB_COM_FILE_SHARE fs WHERE ENT_CODE = #{srchEntCode} AND FUNC_TYPE = 'CUSTOMER' GROUP BY FUNC_JOB_NO ) fs ON fs.ENT_CODE = cus.ENT_CODE AND fs.FUNC_JOB_NO = cus.CUSTOMER_CODE WHERE cus.ENT_CODE = #{srchEntCode} /*AND 1 = (SELECT COUNT(1) FROM TB_SMS_CUSTOMER_SOLUTION sol WHERE sol.ENT_CODE = cus.ENT_CODE AND sol.CUSTOMER_CODE = cus.CUSTOMER_CODE AND sol.SOLUTION = 'ECM')*/
AND cus.CUSTOMER_TYPE = #{srchCustomerType}
AND cus.CUSTOMER_TYPE IN('HC', 'BR','SC')
AND cus.CUSTOMER_CODE = #{srchCustomerCode}
AND cus.CUSTOMER_NAME LIKE CONCAT('%',#{srchCustomerName},'%')

/* SmsCousMapper.selectLoginUserSendModifyYn : 로그인 유저 거래처의 발송수정여부 */
SELECT ISNULL(cus.SEND_MODIFY_YN, 'N')
FROM TB_SMS_USER usr
		 INNER JOIN TB_SMS_CUSTOMER cus
					ON cus.ENT_CODE = usr.ENT_CODE
						AND cus.CUSTOMER_CODE = usr.CUSTOMER_CODE
WHERE usr.ENT_CODE = #{entCode}
  AND usr.USER_ID = #{userId}
